def solution(intervals, new_interval):
    # Add the booking, then merge any overlapping pair and start the search over,
    # until no pair overlaps. Up to n merges, each after an O(n^2) pair search.
    items = [list(x) for x in intervals] + [list(new_interval)]
    merged = True
    while merged:
        merged = False
        for i in range(len(items)):
            for j in range(i + 1, len(items)):
                a, b = items[i], items[j]
                if a[0] <= b[1] and b[0] <= a[1]:
                    items[i] = [min(a[0], b[0]), max(a[1], b[1])]
                    del items[j]
                    merged = True
                    break
            if merged:
                break
    return sorted(items)
